#!/usr/bin/env python3
"""Vue momentum issue des sorties vérifiées, sans anciennes valorisations V3."""
import csv,json
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
def read(p):
 with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def main(root=ROOT):
 d=root/'DONNEES';app=root/'APPLICATION';app.mkdir(exist_ok=True)
 state=json.loads((d/'ETAT_MOMENTUM_QUOTIDIEN.json').read_text())
 ext=json.loads((d/'ETAT_CONFRONTATION_EXTERNES.json').read_text())
 momentum={r['Ticker']:r for r in read(d/'EXPERIENCE_MOMENTUM_40.csv')}
 positions=[dict(momentum.get(r['Ticker'],{}),**r) for r in read(d/'TEST_ETAT_GERE_RECONSTRUIT.csv')]
 watch=read(d/'VIGILANCE_EXTERNES_QUOTIDIENNE.csv')
 payload={'generated_at':datetime.now(timezone.utc).isoformat(),'state':state,'external_state':ext,'positions':positions,
  'candidates':read(d/'CANDIDATS_EXTERNES_MOMENTUM.csv'),'watchlist':watch[:100],
  'journal':read(d/'JOURNAL_ARBITRAGES_GERE.csv'),'valuation':'Non publiée : couverture des données incomplète. Aucun ancien total n’est affiché comme actuel.'}
 (app/'momentum-data.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
 data=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')
 page=TEMPLATE.replace('__DATA__',data)
 (app/'index.html').write_text(page);(root/'index.html').write_text(page)
 print(json.dumps({'positions_actives':sum(r['Statut']=='ACTIF' for r in positions),'candidats':len(payload['candidates']),'vigilance':ext['dossiers_incomplets'],'journal':len(payload['journal'])}))
 return payload

TEMPLATE='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Micro Caps — Momentum</title><style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,sans-serif;background:#0b1119;color:#e8edf5}*{box-sizing:border-box}body{margin:0}main{max-width:1250px;margin:auto;padding:24px}h1{font-size:32px;margin:8px 0}h2{font-size:23px}p{line-height:1.55}small,.muted{color:#a1b1c6;font-size:14px}header{display:flex;justify-content:space-between;gap:18px;align-items:center}.tag{color:#67e8b1;text-transform:uppercase;letter-spacing:.12em;font-size:14px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.card{background:#162130;border:1px solid #2c3d50;padding:20px;border-radius:15px}.card b{display:block;font-size:30px;margin-bottom:8px}.notice{background:#242217;border-left:4px solid #e9bb56;padding:15px 18px;border-radius:8px;margin:18px 0;font-size:16px}.ok{color:#67e8b1}.bad{color:#ff969a}nav{display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #2c3d50;padding-bottom:16px;margin-bottom:22px}button,a.button{font:inherit;border:1px solid #3b526c;border-radius:9px;padding:11px 16px;background:#1b2c40;color:#e8edf5;cursor:pointer}button[aria-selected=true]{background:#256c54;border-color:#67e8b1}button:focus-visible,a:focus-visible{outline:3px solid #e9bb56}a{color:#91c9ff}.scroll{overflow:auto;border:1px solid #2c3d50;border-radius:12px}table{border-collapse:collapse;width:100%;font-size:14px;white-space:nowrap}th,td{padding:13px 12px;border-bottom:1px solid #2c3d50;text-align:right}th{background:#162130;position:sticky;top:0}td:first-child,th:first-child{text-align:left}tr:hover{background:#162130}input{font:inherit;padding:12px;border:1px solid #3b526c;background:#162130;color:white;border-radius:9px;width:min(100%,500px);margin:10px 0 18px}.row{display:flex;justify-content:space-between;gap:14px;align-items:center;flex-wrap:wrap}section[hidden]{display:none}footer{margin:35px 0;color:#a1b1c6;font-size:14px}.pill{display:inline-block;border:1px solid #3b526c;padding:4px 8px;border-radius:7px;font-size:13px}.summary{font-size:18px}#connection{font-size:14px;max-width:340px}@media(max-width:700px){main{padding:16px}header{display:block}.cards{grid-template-columns:repeat(2,1fr)}.card{padding:15px}.card b{font-size:26px}h1{font-size:27px}button{padding:10px 12px}}
</style></head><body><main><header><div><div class="tag">Expérience virtuelle · T0 01/10/2026</div><h1>Micro Caps · Momentum</h1><p class="muted" id="date"></p></div><div><button id="refresh">Actualiser les données</button><p id="connection" role="status">Chargement de l’instantané enregistré…</p></div></header><div id="cards" class="cards"></div><div class="notice" id="scope"></div><nav aria-label="Vues du portefeuille"><button data-tab="portfolio" aria-selected="true">Portefeuille géré</button><button data-tab="external" aria-selected="false">Candidats externes</button><button data-tab="watch" aria-selected="false">Vigilance quotidienne</button><button data-tab="journal" aria-selected="false">Journal virtuel</button></nav>
<section id="portfolio"><h2>Positions après arbitrages</h2><p id="valuation" class="muted"></p><div id="portfolio-table" class="scroll"></div></section>
<section id="external" hidden><h2>Portefeuille contre candidats externes</h2><p id="external-summary" class="summary"></p><p class="muted">Dossier complet = identité, devise, clôture et volume datés, variations 1/5 séances et momentum 1/2/3 mois avec preuves. Les notes SSI/MCPA ne conditionnent pas cette expérience.</p><div id="external-table" class="scroll"></div><p><a id="duels-link">Télécharger la confrontation détaillée</a></p></section>
<section id="watch" hidden><h2>Compléter puis réintégrer</h2><p id="watch-summary"></p><p class="notice">Plejd et Pulsar restent conservées hors arbitrage tant que leurs données ne passent pas les contrôles. Une réintégration n’est pas un achat automatique.</p><input id="search" aria-label="Rechercher parmi les 100 dossiers affichés" placeholder="Rechercher parmi les 100 dossiers affichés"><div id="watch-table" class="scroll"></div><p><a id="watch-link">Télécharger toute la file de vigilance</a></p></section>
<section id="journal" hidden><h2>Opérations réellement journalisées</h2><p id="journal-summary"></p><div id="journal-table" class="scroll"></div><p><a id="journal-link">Ouvrir le journal source</a></p></section><footer>Stratégie momentum uniquement · frais de 2,5 % à l’achat et à la vente · témoin statique de 40 positions · aucune opération réelle.<br>Les données affichent toujours leur date. Une simulation aux clôtures de la veille n’est pas un remplissage boursier réel.</footer></main>
<script id="initial" type="application/json">__DATA__</script><script>
const base='https://raw.githubusercontent.com/HERVE63/MICRO_CAPS_DASHBOARD/repair/microcaps-chain-20261030/';let data=JSON.parse(document.getElementById('initial').textContent);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=(v,d=2)=>v===''||v==null?'—':Number(v).toLocaleString('fr-FR',{maximumFractionDigits:d,minimumFractionDigits:d});const pct=v=>v===''||v==null?'—':(Number(v)>0?'+':'')+num(v)+' %';const label=v=>String(v||'').replaceAll('_',' ').toLowerCase();
function table(id,headers,rows){document.getElementById(id).innerHTML='<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function watch(){const q=document.getElementById('search').value.toLowerCase();table('watch-table',['Candidat','Priorité','À compléter','Archive'],data.watchlist.filter(r=>(r.Ticker+' '+r.Societe).toLowerCase().includes(q)).map(r=>[esc(r.Societe)+'<br><small>'+esc(r.Ticker)+'</small>',esc(r.Priorite_collecte),esc(r.Manquants),esc(r.Date_source_archive)]))}
function render(){const s=data.state,e=data.external_state,active=data.positions.filter(r=>r.Statut==='ACTIF');document.getElementById('date').textContent='Contrôle du '+s.date_execution+' · clôtures de référence : '+(active.find(r=>r.Date_historique)?.Date_historique||'non disponibles');document.getElementById('cards').innerHTML=[[active.length,'positions actives'],[e.titulaires_valides_actifs,'positions avec momentum validé'],[e.dossiers_momentum_complets,'dossiers externes complets relus'],[e.dossiers_incomplets,'cotations externes à compléter']].map(([n,l])=>'<div class="card"><b>'+num(n,0)+'</b>'+esc(l)+'</div>').join('');document.getElementById('scope').textContent='Seuil de démarrage : '+s.seuil_minimum_valides+'/40 · couverture de la cohorte T0 : '+s.lectures_exploitables+'/40. Titulaires exclus : '+s.lignes_exclues.join(', ')+'. Collecte progressive des externes : '+e.dossiers_relus+' relus sur '+e.candidats_repertories+' cotations répertoriées.';document.getElementById('valuation').textContent=data.valuation+' Le témoin conserve ses 40 positions T0.';table('portfolio-table',['Société','État','Quantité','Clôture','Date','1 séance','5 séances','1 mois','2 mois','3 mois'],data.positions.map(r=>[esc(r.Societe)+'<br><small>'+esc(r.Ticker)+'</small>',esc(r.Statut),num(r.Quantite,4),num(r.Cours_devise,4)+' '+esc(r.Devise),esc(r.Date_historique||'—'),...['Variation_derniere_seance_pct','Variation_5_seances_pct','Momentum_1m_pct','Momentum_2m_pct','Momentum_3m_pct'].map(k=>esc(pct(r[k])))]));document.getElementById('external-summary').textContent=e.duels_calcules+' confrontations calculées · '+e.admissibles_achat+' candidat(s) admissible(s) à l’achat · '+e.operations_ajoutees+' opération(s) externe(s) ajoutée(s).';table('external-table',['Candidat','Date','Clôture','1 séance','5 séances','1 mois','2 mois','3 mois','Décision'],data.candidates.map(r=>[esc(r.Societe)+'<br><a href="'+esc(r.Source)+'" target="_blank" rel="noopener">'+esc(r.Ticker)+'</a>',esc(r.Date_historique),num(r.Cours_devise,4)+' '+esc(r.Devise),...['Variation_derniere_seance_pct','Variation_5_seances_pct','Momentum_1m_pct','Momentum_2m_pct','Momentum_3m_pct'].map(k=>esc(pct(r[k]))),esc(label(r.Decision_externe))]));document.getElementById('watch-summary').textContent=e.dossiers_incomplets+' cotations dans la file complète. Extrait des 100 premières priorités ci-dessous. Vérification quotidienne ; collecte navigateur progressive, dates et blocages enregistrés. Aucune visite exhaustive des '+e.candidats_repertories+' cotations n’est revendiquée.';watch();const fees=data.journal.reduce((a,r)=>a+Number(r.Frais_sortie_EUR||0)+Number(r.Frais_entree_EUR||0),0);document.getElementById('journal-summary').textContent=data.journal.length+' écritures exécutées dans le portefeuille virtuel · frais cumulés : '+num(fees)+' €.';table('journal-table',['Date décision','Opération','Valeur','Quantité','Prix local','Frais €'],data.journal.map(r=>[esc(r.Date_decision),esc(label(r.Type_operation)),esc(r.Ticker_sortant||r.Ticker_entrant),num(r.Quantite_vendue||r.Quantite_achetee,4),num(r.Cours_execution_sortie||r.Cours_execution_entree,4)+' '+esc(r.Devise_sortante||r.Devise_entrante),num(r.Frais_sortie_EUR||r.Frais_entree_EUR)]));document.getElementById('duels-link').href=base+'DONNEES/CONFRONTATION_MOMENTUM_EXTERNES.csv';document.getElementById('watch-link').href=base+'DONNEES/VIGILANCE_EXTERNES_QUOTIDIENNE.csv';document.getElementById('journal-link').href=base+'DONNEES/JOURNAL_ARBITRAGES_GERE.csv'}
async function refresh(){const el=document.getElementById('connection');el.textContent='Lecture des résultats GitHub…';try{const r=await fetch(base+'APPLICATION/momentum-data.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error(r.status);const next=await r.json();if(!next.state||!next.external_state||!Array.isArray(next.journal))throw Error('Format invalide');data=next;render();el.textContent='Données GitHub chargées · contrôle du '+data.state.date_execution;}catch(err){el.textContent='Instantané enregistré affiché · actualisation distante indisponible. Contrôle du '+data.state.date_execution;}}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==b.dataset.tab)}));document.getElementById('search').addEventListener('input',watch);document.getElementById('refresh').addEventListener('click',refresh);render();refresh();setInterval(refresh,300000);
</script></body></html>'''
if __name__=='__main__':main()
